# -*- coding: utf-8 -*-
# Pages « punaises de lit » par ville (15 villes où l'habitat collectif et le passage justifient une page dédiée)
_PV = []
def _V(slug, nom, dep, lead, secs, faq, voisins):
    _PV.append((slug, nom, dep, lead, secs, faq, voisins))

_V("laval", "Laval", "53",
 "Piqûres au réveil, taches noires sur le matelas : à Laval, j'interviens chez les particuliers, dans les logements loués et dans les hébergements. Le traitement est thermique, et je me déplace en général sous 24 à 48 heures.",
 [("Pourquoi les punaises de lit circulent à Laval", "Laval est la plus grande ville de la Mayenne et concentre l'essentiel du logement collectif du département : immeubles du centre ancien, résidences, quartiers de logements sociaux, studios et colocations autour des établissements d'enseignement supérieur. Les punaises de lit ne viennent pas de la saleté, elles voyagent avec les gens et leurs bagages. Une ville où l'on déménage souvent, où l'on loue au mois et où l'on héberge des visiteurs est mécaniquement plus exposée.\nDans un immeuble, elles passent d'un logement à l'autre par les gaines, les plinthes et les cloisons mitoyennes. C'est pourquoi un traitement isolé, dans un seul appartement, ne suffit pas toujours : il faut parfois traiter les logements voisins en même temps."),
  ("Locataires, propriétaires et bailleurs", "Beaucoup de mes interventions à Laval concernent des logements loués : appartements, studios étudiants, colocations. Si vous êtes locataire, signalez la situation par écrit à votre propriétaire ou à votre agence dès les premiers signes, et gardez une trace de vos démarches.\nSi vous êtes propriétaire, bailleur ou syndic, faites traiter avant la remise des clés : un logement rendu avec des punaises contamine le locataire suivant dès la première nuit. J'interviens dans les logements vides comme occupés, et je remets un compte rendu écrit que vous pouvez conserver."),
  ("Hôtels, gîtes et hébergements", "Laval accueille des voyageurs tout au long de l'année : hôtels, chambres d'hôtes, logements de courte durée près de la gare et du centre. Pour un hébergeur, une punaise de lit, c'est un avis en ligne qui reste des années. J'interviens discrètement, en dehors des heures de passage quand c'est possible, et je peux contrôler les chambres voisines de celle qui est touchée."),
  ("Mon intervention à Laval", "Je commence par un diagnostic : j'inspecte le matelas, le sommier, les coutures, les plinthes, les meubles et les cadres pour mesurer l'étendue réelle de l'infestation. J'interviens ensuite de manière thermique : la chaleur atteint les punaises et leurs œufs dans leurs cachettes, sans laisser d'odeur de produit dans le logement.\nJe vous explique avant mon passage ce qu'il faut préparer, et je contrôle le résultat ensuite. Laval est à quinze minutes de Port-Brillet : je m'y rends rapidement, y compris en soirée.")],
 [("Intervenez-vous dans les appartements à Laval ?", "Oui, c'est l'essentiel de mes interventions en ville. Je traite le logement concerné et je vous dis s'il faut vérifier les logements voisins."),
  ("Je suis locataire à Laval, pouvez-vous intervenir ?", "Oui. Prévenez votre propriétaire ou votre agence, puis appelez-moi : je peux traiter le logement et remettre un compte rendu écrit à qui en a besoin."),
  ("Combien de temps faut-il pour traiter un appartement ?", "Cela dépend de la surface et de l'ampleur. Je vous l'indique dès le diagnostic, avec le nombre de passages nécessaires.")],
 ["saint-berthevin", "change", "bonchamp-les-laval", "mayenne"])

_V("rennes", "Rennes", "35",
 "Rennes est la ville de mon secteur où les punaises de lit circulent le plus. J'interviens dans les appartements, les colocations, les logements étudiants et les hébergements, avec un traitement thermique.",
 [("Une ville étudiante, donc très exposée", "Rennes est l'une des villes les plus étudiantes de France. Chaque année, des milliers de logements changent d'occupant, souvent meublés, avec des matelas, des sommiers et des canapés qui restent en place d'un locataire à l'autre. Ajoutez les colocations, les résidences, les voyages et les déménagements de fin d'année : ce sont les conditions idéales pour que les punaises de lit se déplacent.\nElles ne sont pas un signe de malpropreté. Elles voyagent dans les sacs, les valises et les meubles d'occasion, et elles tiennent des mois sans se nourrir en attendant un nouvel occupant."),
  ("Immeubles, colocations et meublés", "Dans un immeuble rennais, les punaises passent d'un logement à l'autre par les cloisons, les gaines et les plinthes. En colocation, chaque chambre doit être inspectée, même si une seule personne se fait piquer : les punaises se logent dans les lits mais aussi dans les canapés et les fauteuils des pièces communes.\nPour un meublé, le mobilier reste sur place entre deux locataires, ce qui explique qu'une infestation puisse réapparaître sans que personne n'ait rien rapporté."),
  ("Agences, bailleurs et résidences", "Je travaille régulièrement avec des agences immobilières et des gestionnaires de résidences. Traiter entre deux locations évite une réclamation, un litige et un avis public. Je remets un compte rendu écrit après chaque passage, et je peux intervenir sur plusieurs logements d'un même immeuble dans la même journée."),
  ("Mon intervention à Rennes", "Je me déplace à Rennes depuis la Mayenne, en général sous 24 à 48 heures. Je commence par un diagnostic complet : matelas, sommier, coutures, plinthes, meubles, canapés. J'interviens ensuite de manière thermique, une méthode qui atteint les punaises et leurs œufs jusque dans les coutures et les interstices, sans odeur de produit.\nJe vous dis avant mon passage ce qu'il faut préparer, et je contrôle le résultat ensuite.")],
 [("Intervenez-vous à Rennes depuis la Mayenne ?", "Oui, Rennes fait partie de mon secteur. Appelez-moi : je vous donne un créneau, en général sous 24 à 48 heures."),
  ("Faut-il traiter toute la colocation ?", "Il faut au minimum inspecter chaque chambre et les pièces communes. Traiter une seule chambre laisse souvent repartir l'infestation."),
  ("Je suis propriétaire d'un meublé, dois-je jeter le matelas ?", "Pas systématiquement. Le traitement thermique permet le plus souvent de conserver le matelas et le sommier. Je vous le dis après le diagnostic.")],
 ["cesson-sevigne", "chateaubourg", "chateaugiron", "vitre"])

_V("vitre", "Vitré", "35",
 "À Vitré, j'interviens contre les punaises de lit dans les logements du centre ancien, les locations et les hébergements touristiques. Traitement thermique et déplacement en général sous 24 à 48 heures.",
 [("Un centre ancien très dense", "Le centre de Vitré est fait de maisons à pans de bois, d'immeubles anciens et d'appartements mitoyens autour du château et des rues historiques. Les planchers, les plinthes, les lambris et les cloisons anciennes offrent aux punaises de lit une quantité de cachettes que l'on ne trouve pas dans une construction récente.\nCe bâti mitoyen explique aussi qu'une infestation puisse passer d'un logement à l'autre : les punaises circulent par les interstices des planchers et des murs partagés."),
  ("Tourisme, gîtes et chambres d'hôtes", "Vitré est une ville visitée toute l'année pour son château et sa cité médiévale. Les hébergements touristiques, gîtes, chambres d'hôtes et locations de courte durée voient se succéder des voyageurs et leurs valises : c'est le principal mode de propagation des punaises de lit.\nPour un hébergeur, une détection précoce change tout. Je peux inspecter une chambre au moindre doute, traiter si nécessaire et contrôler les chambres voisines."),
  ("Locations et logements du parc privé", "J'interviens aussi dans les appartements loués, les studios et les maisons de ville. Si vous êtes locataire, signalez la situation par écrit à votre propriétaire dès les premiers signes. Si vous êtes propriétaire, faites traiter entre deux locataires : c'est bien moins coûteux qu'une infestation installée."),
  ("Mon intervention à Vitré", "Vitré fait partie de mon secteur historique. J'inspecte le matelas, le sommier, les coutures, les plinthes et les meubles, puis j'interviens de manière thermique : la chaleur élimine les punaises et leurs œufs dans leurs cachettes, ce qui est particulièrement utile dans un bâti ancien plein d'interstices. Je contrôle ensuite le résultat.")],
 [("Intervenez-vous dans les gîtes et chambres d'hôtes à Vitré ?", "Oui, et discrètement. Je peux intervenir en dehors des périodes de forte fréquentation et contrôler les chambres voisines."),
  ("Mon logement est ancien, est-ce un problème pour le traitement ?", "Non. Le traitement thermique est justement adapté aux planchers, plinthes et lambris anciens, où les punaises se cachent."),
  ("Faut-il jeter les meubles ?", "Rarement. Le traitement permet le plus souvent de tout conserver. Je vous le dis après le diagnostic.")],
 ["chateaubourg", "argentre-du-plessis", "rennes", "fougeres"])

_V("fougeres", "Fougères", "35",
 "À Fougères, je traite les punaises de lit dans les appartements, les logements loués et les hébergements. Intervention thermique, en général sous 24 à 48 heures.",
 [("Un parc de logements ancien et collectif", "Fougères associe une ville haute ancienne, des immeubles de centre-ville et plusieurs quartiers de logement collectif. Ce type de parc, fait de bâti ancien et d'appartements mitoyens, favorise la circulation des punaises de lit d'un logement à l'autre par les gaines, les plinthes et les cloisons.\nLes punaises n'ont rien à voir avec le manque d'hygiène : elles arrivent dans une valise, un sac, un meuble d'occasion ou depuis l'appartement voisin, puis s'installent dans les coutures du matelas et les interstices proches du lit."),
  ("Tourisme et hébergements", "Le château de Fougères et la ville médiévale attirent des visiteurs toute l'année. Hôtels, gîtes et locations de courte durée sont donc exposés : les voyageurs transportent les punaises sans le savoir. Pour un hébergeur, une inspection au moindre doute évite une infestation généralisée et des avis en ligne difficiles à rattraper."),
  ("Bailleurs, agences et syndics", "J'interviens pour des propriétaires, des agences et des syndics du secteur de Fougères, dans des logements occupés comme vides. Traiter entre deux locataires évite de transmettre le problème au suivant. Après chaque passage, je remets un compte rendu écrit, utile en cas de litige ou pour informer la copropriété."),
  ("Mon intervention à Fougères", "Je commence par un diagnostic sérieux : l'étendue réelle d'une infestation se juge au matelas, au sommier, aux coutures, aux plinthes et aux meubles, pas au nombre de punaises visibles. J'interviens ensuite de manière thermique, sans odeur de produit, puis je contrôle le résultat. Fougères fait partie de mon secteur régulier.")],
 [("Fougères fait-elle partie de votre zone ?", "Oui. Je m'y déplace régulièrement, en général sous 24 à 48 heures."),
  ("Mon voisin a des punaises, que dois-je faire ?", "Faites inspecter votre logement sans attendre, même sans piqûre : dans un immeuble, les punaises passent par les cloisons et les gaines."),
  ("Le traitement laisse-t-il une odeur ?", "Le traitement thermique ne laisse pas d'odeur de produit, ce qui permet de réoccuper la pièce rapidement.")],
 ["vitre", "saint-aubin-du-cormier", "ernee", "mayenne"])

_V("mayenne", "Mayenne", "53",
 "À Mayenne, j'interviens contre les punaises de lit dans les appartements, les maisons, les logements loués et les hébergements, avec un traitement thermique.",
 [("Des logements anciens au cœur de la ville", "La ville de Mayenne s'organise de part et d'autre de la rivière, avec un centre ancien, des immeubles de rapport et plusieurs ensembles de logements collectifs. Dans un bâti ancien, les punaises de lit trouvent des cachettes dans les plinthes, les parquets, les lambris et les cloisons.\nUne infestation ne se mesure pas au nombre de punaises visibles : les adultes que l'on aperçoit ne représentent qu'une petite partie de la population, le reste se tenant dans les coutures, les interstices et les vis des sommiers."),
  ("Locations, résidences et établissements", "J'interviens dans des appartements loués, des studios, des résidences et des établissements accueillant du public. Dans ces lieux, les allées et venues des occupants et de leurs affaires suffisent à transporter les punaises. Un signalement rapide permet de traiter une seule chambre plutôt qu'un étage entier."),
  ("Particuliers et maisons individuelles", "Beaucoup de mes clients à Mayenne sont des particuliers qui ont rapporté des punaises d'un voyage, d'un hôtel, d'un meuble d'occasion ou d'un séjour chez des proches. Ne déplacez pas le matelas ni les meubles dans d'autres pièces avant mon passage : vous disperseriez les punaises dans tout le logement."),
  ("Mon intervention à Mayenne", "Je commence par inspecter la literie, les coutures, les plinthes et les meubles pour savoir jusqu'où l'infestation s'est étendue. J'interviens ensuite de manière thermique : la chaleur atteint les punaises et leurs œufs dans leurs cachettes. Je vous indique avant mon passage ce qu'il faut préparer, et je contrôle le résultat ensuite.")],
 [("Intervenez-vous à Mayenne pour un seul appartement ?", "Oui. Je traite aussi bien un studio qu'une maison entière."),
  ("Dois-je jeter mon matelas ?", "Le plus souvent non : le traitement thermique permet de le conserver. Je vous le dis après le diagnostic."),
  ("Combien de passages faut-il ?", "Cela dépend de l'ampleur. Je vous l'indique dès le diagnostic, avant toute intervention.")],
 ["ernee", "montflours", "laval", "fougeres"])

_V("chateau-gontier", "Château-Gontier", "53",
 "À Château-Gontier-sur-Mayenne, je traite les punaises de lit dans les logements, les locations et les hébergements. Traitement thermique et compte rendu écrit.",
 [("Une ville de logement collectif au sud du département", "Château-Gontier-sur-Mayenne est la deuxième ville du sud-Mayenne, avec un centre ancien, des immeubles et plusieurs ensembles de logements collectifs. Ce type de parc favorise la circulation des punaises de lit d'un appartement à l'autre, par les gaines, les plinthes et les cloisons mitoyennes.\nUne punaise de lit se glisse dans un espace de l'épaisseur d'une carte bancaire : il n'y a pas de logement trop propre ou trop neuf pour en accueillir."),
  ("Locations, meublés et hébergements", "Les meublés et les locations de courte durée voient se succéder des occupants et leurs bagages, qui sont le premier mode de transport des punaises. Pour un propriétaire ou un hébergeur, le traitement entre deux locations est la seule façon de rompre la chaîne.\nJ'interviens dans les logements vides comme occupés, et je remets un compte rendu écrit après chaque passage."),
  ("Ce que vous pouvez faire avant mon passage", "Ne déplacez pas les meubles ni le matelas dans d'autres pièces : vous disperseriez l'infestation. Lavez le linge de lit à 60 °C si le textile le permet, et rangez le linge propre dans des sacs fermés. Évitez les produits du commerce sur le lit : ils font fuir les punaises vers d'autres pièces sans régler le problème."),
  ("Mon intervention à Château-Gontier", "Je commence par un diagnostic de la literie, des coutures, des plinthes et des meubles. J'interviens ensuite de manière thermique, sans laisser d'odeur de produit, puis je contrôle le résultat. Château-Gontier fait partie de ma zone d'intervention régulière.")],
 [("Intervenez-vous à Château-Gontier-sur-Mayenne ?", "Oui, la commune fait partie de mon secteur. Appelez-moi pour un créneau."),
  ("Les produits du commerce peuvent-ils suffire ?", "Rarement pour une infestation installée : les œufs et les cachettes résistent, et les sprays dispersent les punaises dans le logement."),
  ("Puis-je rester chez moi pendant le traitement ?", "Je vous le précise avant l'intervention, selon le traitement et la configuration du logement.")],
 ["craon", "meslay-du-maine", "laval", "renaze"])

_V("cesson-sevigne", "Cesson-Sévigné", "35",
 "À Cesson-Sévigné, j'interviens contre les punaises de lit dans les logements, les résidences et les hébergements professionnels. Traitement thermique, discret et rapide.",
 [("Une commune résidentielle et d'affaires", "Cesson-Sévigné appartient à la métropole rennaise et associe des quartiers résidentiels, des résidences récentes et un important tissu d'entreprises et de centres de formation. Cette fréquentation, faite de déplacements professionnels, de séjours courts et de logements temporaires, est exactement ce qui fait circuler les punaises de lit.\nElles voyagent dans les valises et les sacs, puis s'installent dans les coutures des matelas, les sommiers et les interstices proches du lit."),
  ("Hébergements, résidences et logements temporaires", "Les hôtels d'affaires, les résidences et les logements loués pour quelques semaines sont les lieux les plus exposés : chaque nouvel occupant est une occasion d'introduction. Pour un gestionnaire, une inspection rapide au moindre signalement évite de devoir traiter un étage entier.\nJ'interviens discrètement, et je remets un compte rendu écrit après chaque passage."),
  ("Particuliers et maisons individuelles", "Dans les quartiers résidentiels, l'origine est souvent un voyage, un séjour à l'hôtel, un meuble d'occasion ou la visite de proches. Si vous vous réveillez avec des piqûres alignées sur les bras ou les jambes, ne déplacez rien et appelez-moi : le diagnostic dira jusqu'où l'infestation s'est étendue."),
  ("Mon intervention à Cesson-Sévigné", "Je me déplace depuis la Mayenne, en général sous 24 à 48 heures. Après le diagnostic, j'interviens de manière thermique : la chaleur atteint les punaises et leurs œufs jusque dans les coutures, sans odeur de produit, ce qui permet de réoccuper les lieux rapidement.")],
 [("Intervenez-vous pour les entreprises et les résidences ?", "Oui. J'interviens dans les hébergements professionnels et les résidences, avec un compte rendu écrit après chaque passage."),
  ("Le traitement est-il discret ?", "Oui. Je peux intervenir en dehors des heures de passage et sans signalétique."),
  ("Combien de temps avant de pouvoir réoccuper la pièce ?", "Je vous le précise avant l'intervention : le traitement thermique permet en général de reprendre l'usage de la pièce rapidement.")],
 ["rennes", "chateaubourg", "chateaugiron", "servon-sur-vilaine"])

_V("chateaubourg", "Châteaubourg", "35",
 "À Châteaubourg, je traite les punaises de lit dans les maisons, les appartements et les hébergements. Traitement thermique, devis gratuit, déplacement compris.",
 [("Entre Rennes et Vitré, une commune de passage", "Châteaubourg est située sur l'axe entre Rennes et Vitré, avec une population qui travaille souvent dans la métropole rennaise. Ces allers-retours quotidiens, les déménagements et les séjours chez des proches suffisent à faire circuler les punaises de lit, qui voyagent dans les sacs et les valises.\nLa commune compte des lotissements récents comme des logements anciens de bourg : les deux peuvent être touchés, car les punaises ne dépendent ni de l'âge du bâti ni de la propreté du logement."),
  ("Reconnaître une infestation", "Les signes les plus fiables sont des piqûres groupées ou alignées au réveil, de petits points noirs sur les draps ou le long des coutures du matelas, des traces de sang sur les draps et de minuscules peaux translucides, les mues, près du lit. Les punaises se logent dans les coutures du matelas, les lattes et les vis du sommier, derrière la tête de lit, dans les plinthes et dans les meubles proches."),
  ("Locations et hébergements", "J'interviens pour des propriétaires, des locataires et des hébergeurs du secteur. Pour une location, le traitement entre deux occupants est le moment le plus efficace : le logement est vide, l'accès est complet et personne ne subit l'infestation suivante."),
  ("Mon intervention à Châteaubourg", "Je commence par un diagnostic de la literie, des plinthes et des meubles pour mesurer l'étendue réelle. J'interviens ensuite de manière thermique : la chaleur élimine les punaises à tous les stades, œufs compris, là où elles se cachent. Je contrôle le résultat après mon passage.")],
 [("Châteaubourg fait-elle partie de votre secteur ?", "Oui, la commune est sur mon axe habituel entre Vitré et Rennes."),
  ("Les piqûres sont-elles dangereuses ?", "Elles provoquent surtout des démangeaisons, et le grattage peut s'infecter. Pour une question médicale, voyez votre médecin."),
  ("Dois-je tout laver avant votre passage ?", "Je vous donne des consignes précises avant l'intervention. Ne déplacez rien dans d'autres pièces en attendant.")],
 ["vitre", "servon-sur-vilaine", "cesson-sevigne", "domagne"])

_V("saint-berthevin", "Saint-Berthevin", "53",
 "À Saint-Berthevin, j'interviens rapidement contre les punaises de lit : maisons, appartements, logements loués. Traitement thermique, à dix minutes de chez moi.",
 [("Une commune résidentielle aux portes de Laval", "Saint-Berthevin est la voisine immédiate de Laval et compte à la fois des lotissements, des immeubles et des logements loués. La proximité de l'agglomération lavalloise fait que les habitants, les locataires et les visiteurs circulent constamment entre les deux communes : les punaises de lit circulent avec eux.\nUne punaise de lit n'est pas liée à la propreté du logement. Elle arrive dans une valise, un sac de voyage, un meuble d'occasion ou depuis un logement voisin, puis s'installe à quelques mètres du lit."),
  ("Un déplacement très court", "Saint-Berthevin se trouve à une dizaine de kilomètres de Port-Brillet, où je suis installé. C'est l'une des communes où j'interviens le plus vite, y compris en fin de journée. Si vous découvrez des piqûres au réveil, appelez-moi le jour même : plus l'infestation est récente, plus le traitement est simple."),
  ("Avant et après mon passage", "Avant : ne déplacez pas le matelas, le sommier ni les meubles dans d'autres pièces, et ne traitez pas vous-même avec des produits du commerce, qui dispersent les punaises. Lavez le linge de lit à 60 °C si le textile le permet.\nAprès : suivez les consignes que je vous donne, notamment sur le lavage des sols et la remise en place du mobilier. Je contrôle le résultat et je repasse si nécessaire."),
  ("Mon intervention à Saint-Berthevin", "Je commence par un diagnostic complet de la chambre et des pièces voisines, puis j'interviens de manière thermique. La chaleur atteint les punaises et leurs œufs dans les coutures, les plinthes et les meubles, sans odeur de produit dans le logement.")],
 [("Êtes-vous proche de Saint-Berthevin ?", "Oui, à une dizaine de kilomètres. C'est l'une des communes où j'interviens le plus rapidement."),
  ("Intervenez-vous le soir ?", "Je suis disponible jusqu'à 21h en semaine et jusqu'à 18h le week-end."),
  ("Puis-je garder mes meubles ?", "Le plus souvent oui. Le traitement thermique permet de conserver matelas, sommier et mobilier dans la plupart des cas.")],
 ["laval", "le-genest-saint-isle", "change", "loiron-ruille"])

_V("ernee", "Ernée", "53",
 "À Ernée, je traite les punaises de lit dans les maisons, les appartements et les logements loués. Traitement thermique, devis gratuit.",
 [("Une petite ville, des logements de bourg", "Ernée est une petite ville de la Mayenne, avec un centre de bourg fait de maisons mitoyennes, d'appartements au-dessus des commerces et de logements anciens. Ces logements partagent des murs, des planchers et parfois des combles : autant de passages que les punaises de lit peuvent emprunter.\nOn croit souvent que les punaises de lit sont un problème de grande ville. C'est faux : elles arrivent partout où des personnes se déplacent, avec un bagage, un meuble d'occasion ou un séjour chez des proches."),
  ("Ce qu'il faut regarder", "Inspectez les coutures et les étiquettes du matelas, les lattes et les vis du sommier, l'arrière de la tête de lit, les plinthes derrière le lit et les meubles les plus proches. Cherchez de petits points noirs, des traces de sang sur les draps et de minuscules peaux translucides.\nSi vous trouvez quelque chose, ne déplacez rien et prenez une photo : cela me permet de préparer mon intervention."),
  ("Locations et hébergements du secteur", "J'interviens pour des propriétaires, des locataires et des hébergeurs d'Ernée et des communes voisines. Dans une location, le traitement entre deux occupants est le plus efficace : le logement est vide, j'ai accès à tout et le locataire suivant ne subit rien."),
  ("Mon intervention à Ernée", "Après le diagnostic, j'interviens de manière thermique : la chaleur élimine les punaises à tous les stades, œufs compris, jusque dans les coutures et les interstices. Il n'y a pas d'odeur de produit dans le logement. Je contrôle ensuite le résultat.")],
 [("Ernée fait-elle partie de votre secteur ?", "Oui, c'est une commune où j'interviens régulièrement."),
  ("Est-ce que cela arrive vraiment en campagne ?", "Oui. Les punaises de lit voyagent avec les personnes, pas avec la saleté ni avec la taille de la commune."),
  ("Faut-il traiter plusieurs fois ?", "Cela dépend de l'ampleur de l'infestation. Je vous le dis dès le diagnostic.")],
 ["mayenne", "saint-denis-de-gastines", "laval", "fougeres"])

_V("change", "Changé", "53",
 "À Changé, j'interviens contre les punaises de lit dans les maisons, les appartements et les logements loués. Traitement thermique, intervention rapide.",
 [("Une commune résidentielle au nord de Laval", "Changé est une commune résidentielle en forte croissance au nord de Laval, avec des lotissements récents, des maisons individuelles et des logements collectifs. Les habitants travaillent souvent à Laval ou plus loin, et les familles reçoivent, voyagent et déménagent : c'est ainsi que les punaises de lit arrivent dans un logement.\nUn logement neuf n'est pas protégé. Les punaises ne viennent pas de la construction ni de l'entretien : elles sont apportées dans un bagage, un carton de déménagement ou un meuble d'occasion."),
  ("Le cas des meubles d'occasion", "Beaucoup d'infestations commencent par un canapé, un matelas, une tête de lit ou un cadre de lit récupérés d'occasion. Si vous reprenez un meuble, inspectez les coutures, les plis et les fentes avant de l'entrer chez vous, et évitez les matelas et sommiers récupérés sur un trottoir.\nSi le meuble est déjà installé et que les piqûres ont commencé, ne le ressortez pas par la maison : appelez-moi d'abord."),
  ("Avant mon passage", "Ne déplacez pas le matelas ni les meubles dans d'autres pièces, et n'utilisez pas de produits du commerce sur le lit : ils dispersent les punaises dans tout le logement sans traiter les œufs. Lavez le linge de lit à 60 °C si le textile le permet, puis rangez-le dans des sacs fermés."),
  ("Mon intervention à Changé", "Je commence par un diagnostic de la literie, des plinthes et des meubles. J'interviens ensuite de manière thermique, sans odeur de produit, et je contrôle le résultat. Changé est à une vingtaine de minutes de Port-Brillet.")],
 [("Intervenez-vous rapidement à Changé ?", "Oui, la commune est proche de ma base : je m'y rends en général sous 24 à 48 heures."),
  ("J'ai récupéré un canapé, est-ce la cause ?", "C'est une cause fréquente. Le diagnostic permet de savoir d'où part l'infestation."),
  ("Mon logement est récent, est-ce possible ?", "Oui. Les punaises de lit sont apportées par les personnes et les objets, pas par l'état du logement.")],
 ["laval", "louverne", "saint-berthevin", "montflours"])

_V("bonchamp-les-laval", "Bonchamp-lès-Laval", "53",
 "À Bonchamp-lès-Laval, je traite les punaises de lit dans les maisons, les appartements et les locations. Traitement thermique et déplacement compris dans le tarif.",
 [("Une commune familiale à l'est de Laval", "Bonchamp-lès-Laval est une commune résidentielle en bordure de Laval, faite surtout de maisons individuelles, de lotissements et de quelques ensembles collectifs. Les familles y reçoivent, voyagent, hébergent des proches et déménagent : ce sont ces mouvements, et non l'entretien du logement, qui font entrer les punaises de lit.\nUne fois dans la maison, elles se tiennent à moins de quelques mètres du lit : matelas, sommier, tête de lit, plinthes et meubles proches."),
  ("Les enfants et les chambres", "Dans une maison de famille, l'infestation est souvent repérée dans la chambre d'un enfant, parce que les piqûres marquent plus vite. Inspectez le lit du dessus comme celui du dessous dans un lit superposé, les peluches posées sur le lit et le matelas des lits d'appoint, qui restent parfois longtemps sans être ouverts.\nNe déplacez pas la literie dans une autre pièce : vous installeriez le problème ailleurs."),
  ("Retours de vacances et séjours", "Les punaises de lit se rapportent très souvent d'un séjour : hôtel, location, camping, famille. Au retour, ne posez pas la valise sur le lit, inspectez-la et lavez le linge à 60 °C si le textile le permet. C'est le geste simple qui évite le plus d'infestations."),
  ("Mon intervention à Bonchamp-lès-Laval", "Je commence par un diagnostic complet de la chambre concernée et des pièces voisines, puis j'interviens de manière thermique : la chaleur atteint les punaises et leurs œufs dans leurs cachettes, sans odeur de produit. Je contrôle ensuite le résultat.")],
 [("Intervenez-vous à Bonchamp-lès-Laval ?", "Oui, la commune est proche de Laval et fait partie de mon secteur régulier."),
  ("Faut-il traiter toute la maison ?", "Pas toujours. Le diagnostic détermine les pièces concernées : les punaises restent le plus souvent près du lit."),
  ("Les peluches et les textiles sont-ils traités ?", "Je vous indique ce qui doit être lavé, isolé ou laissé en place avant mon passage.")],
 ["laval", "change", "louverne", "saint-berthevin"])

_V("la-guerche-de-bretagne", "La Guerche-de-Bretagne", "35",
 "À La Guerche-de-Bretagne, je traite les punaises de lit dans les logements du bourg, les locations et les hébergements. Traitement thermique.",
 [("Un bourg ancien et commerçant", "La Guerche-de-Bretagne est un bourg historique, connu pour son marché et sa place à galeries. Le centre est fait de maisons anciennes et d'appartements situés au-dessus des commerces, souvent mitoyens et reliés par des planchers et des cloisons anciennes.\nCe bâti offre aux punaises de lit de nombreuses cachettes, et permet à une infestation de passer d'un logement à l'autre. Elles ne dépendent ni de la propreté ni de l'ancienneté : elles sont apportées par les personnes et les objets."),
  ("Locations, meublés et hébergements", "Les logements loués et les meublés du bourg voient se succéder des occupants. Pour un propriétaire, le moment le plus efficace pour traiter est entre deux locations : l'accès est complet et le locataire suivant ne subit rien. Je remets un compte rendu écrit après chaque passage."),
  ("Les signes qui doivent alerter", "Des piqûres groupées au réveil, surtout sur les bras, les épaules et les jambes, de petits points noirs le long des coutures du matelas, des traces de sang sur les draps et de minuscules peaux translucides près du lit. Si vous constatez l'un de ces signes, ne déplacez rien et appelez-moi."),
  ("Mon intervention à La Guerche-de-Bretagne", "Après un diagnostic de la literie, des plinthes et des meubles, j'interviens de manière thermique : la chaleur élimine les punaises et leurs œufs dans les coutures et les interstices, ce qui est particulièrement adapté au bâti ancien. Je contrôle ensuite le résultat.")],
 [("Intervenez-vous à La Guerche-de-Bretagne ?", "Oui, la commune fait partie de mon secteur en Ille-et-Vilaine."),
  ("Mon appartement est au-dessus d'un commerce, est-ce un problème ?", "Non, mais j'inspecte les passages possibles avec les locaux voisins pour éviter une réinfestation."),
  ("Combien de temps dure une intervention ?", "Cela dépend de la surface et de l'ampleur. Je vous le dis dès le diagnostic.")],
 ["retiers", "argentre-du-plessis", "vitre", "etrelles"])

_V("craon", "Craon", "53",
 "À Craon, j'interviens contre les punaises de lit dans les maisons, les appartements et les hébergements. Traitement thermique, devis gratuit.",
 [("Une petite ville du sud-Mayenne", "Craon est une petite ville du sud de la Mayenne, avec un centre ancien, des maisons de bourg mitoyennes et quelques ensembles de logements collectifs. Ce bâti partagé, fait de murs et de planchers communs, permet aux punaises de lit de circuler d'un logement à l'autre.\nElles sont apportées par les personnes et leurs affaires : un bagage, un meuble d'occasion, un séjour chez des proches. Rien à voir avec l'entretien du logement."),
  ("Événements, hébergements et séjours", "Craon accueille régulièrement du public, notamment autour de son hippodrome et de ses événements. Les hébergements qui reçoivent des visiteurs, gîtes, chambres d'hôtes et locations de courte durée, sont les plus exposés, car chaque nouveau séjour est une occasion d'introduction. Une inspection au moindre doute coûte bien moins cher qu'un traitement généralisé."),
  ("Avant mon passage", "Ne déplacez pas le matelas, le sommier ni les meubles dans d'autres pièces. N'utilisez pas de bombes ou de sprays du commerce : ils dispersent les punaises sans traiter les œufs. Lavez le linge de lit à 60 °C si le textile le permet, puis rangez-le dans des sacs fermés en attendant."),
  ("Mon intervention à Craon", "Je commence par un diagnostic de la literie, des coutures, des plinthes et des meubles, puis j'interviens de manière thermique. La chaleur atteint les punaises et leurs œufs dans leurs cachettes, sans odeur de produit. Je contrôle ensuite le résultat.")],
 [("Craon fait-elle partie de votre zone ?", "Oui, j'interviens dans le sud de la Mayenne, Craon compris."),
  ("Intervenez-vous dans les gîtes et chambres d'hôtes ?", "Oui, discrètement, et je peux contrôler les chambres voisines de celle qui est touchée."),
  ("Puis-je conserver mon matelas ?", "Le plus souvent oui, grâce au traitement thermique. Je vous le confirme après le diagnostic.")],
 ["cosse-le-vivien", "renaze", "chateau-gontier", "quelaines-saint-gault"])

_V("chateaugiron", "Châteaugiron", "35",
 "À Châteaugiron, je traite les punaises de lit dans les maisons, les appartements et les hébergements. Traitement thermique, intervention en général sous 24 à 48 heures.",
 [("Une petite cité très fréquentée", "Châteaugiron est une petite cité de caractère, avec son château et son centre ancien, située à proximité immédiate de Rennes. Elle reçoit des visiteurs et accueille une population qui travaille souvent dans la métropole : ces déplacements quotidiens et ces séjours font circuler les punaises de lit.\nLe centre ancien, avec ses maisons mitoyennes et ses appartements, offre des cachettes dans les planchers, les plinthes et les cloisons. Les lotissements récents ne sont pas épargnés pour autant : les punaises arrivent avec les personnes, pas avec le bâti."),
  ("Proximité de Rennes", "Beaucoup d'habitants de Châteaugiron se rendent quotidiennement à Rennes, qui est la ville de mon secteur où les punaises circulent le plus. Les transports, les lieux publics et les logements étudiants de la métropole sont des points de contact possibles. Une infestation détectée tôt se traite en une intervention."),
  ("Hébergements et locations", "Pour les gîtes, chambres d'hôtes et locations de courte durée du secteur, le traitement entre deux séjours est la meilleure protection. J'interviens discrètement et je remets un compte rendu écrit, utile pour vos obligations vis-à-vis des voyageurs."),
  ("Mon intervention à Châteaugiron", "Je me déplace depuis la Mayenne, en général sous 24 à 48 heures. Après un diagnostic de la literie, des plinthes et des meubles, j'interviens de manière thermique : la chaleur élimine les punaises et leurs œufs jusque dans les coutures. Je contrôle ensuite le résultat.")],
 [("Intervenez-vous à Châteaugiron ?", "Oui, la commune fait partie de mon secteur autour de Rennes."),
  ("Mon logement est récent, suis-je concerné ?", "Oui, cela peut arriver partout : les punaises sont apportées par les personnes et les objets."),
  ("Le traitement thermique abîme-t-il les meubles ?", "Je règle le traitement selon les matériaux et je vous indique avant mon passage ce qu'il faut retirer de la pièce.")],
 ["cesson-sevigne", "rennes", "domagne", "servon-sur-vilaine"])

# ---------- RENDU ----------
_PUN_NOMS = {s: n for s, n, *_ in _PV}

def _titre_pun(nom, dep):
    for t in ("Punaises de Lit %s (%s) | Proxinuisibles" % (nom, dep),
              "Punaises de Lit %s | Proxinuisibles" % nom,
              "Punaises de Lit %s" % nom):
        if len(t) <= 60:
            return t
    return "Punaises de Lit %s" % nom

def _meta_pun(nom, dep):
    for m in ("Traitement des punaises de lit à %s (%s) : diagnostic, traitement thermique et suivi. Particuliers, locations et hébergements. Devis gratuit." % (nom, dep),
              "Traitement des punaises de lit à %s (%s) : diagnostic, traitement thermique, suivi. Particuliers et locations. Devis gratuit." % (nom, dep),
              "Punaises de lit à %s (%s) : diagnostic, traitement thermique et suivi. Devis gratuit." % (nom, dep)):
        if len(m) <= 155:
            return m
    return "Punaises de lit à %s : traitement thermique et suivi." % nom

for slug, nom, dep, lead, secs, faq, voisins in _PV:
    path = "/punaises-de-lit-%s/" % slug
    if path in P:
        continue
    vlinks = [("Punaises de lit à %s" % _PUN_NOMS[v], "/punaises-de-lit-%s/" % v) for v in voisins if v in _PUN_NOMS]
    vlinks += [("Dératisation à %s" % _NOMS[v], "/deratisation-%s/" % v) for v in voisins if v not in _PUN_NOMS and v in _NOMS and ("/deratisation-%s/" % v) in P]
    vlinks = [(l, u) for l, u in vlinks if u != path][:4]
    links = [("Autres services à %s" % nom,
              [("Dératisation", "/deratisation-%s/" % slug if ("/deratisation-%s/" % slug) in P else "/deratisation/"),
               ("Frelons et guêpes", "/frelons-guepes/"), ("Frelon asiatique", "/frelon-asiatique/"),
               ("Blattes et cafards", "/blattes-cafards/"), ("Puces", "/puces/"), ("Désinsectisation", "/desinsectisation/")])]
    if vlinks:
        links.append(("À proximité", vlinks))
    links.append(("Voir aussi", [("Tout sur les punaises de lit", "/punaises-de-lit/"), ("Agences et syndics", "/agences-syndics/"),
                                 ("Zones d'intervention", "/zones-intervention/"), ("Devis et contact", "/contact/")]))
    add(path, h1="Punaises de lit à %s (%s) : traitement thermique" % (nom, dep),
        title=_titre_pun(nom, dep), meta=_meta_pun(nom, dep),
        lead=lead, secs=secs, faq=faq, links=links, kind="ville")

P["/punaises-de-lit/"]["links"] = list(P["/punaises-de-lit/"].get("links") or []) + [
    ("Punaises de lit, ville par ville", [("Punaises de lit à %s" % n, "/punaises-de-lit-%s/" % s) for s, n, *_ in _PV])]
P["/zones-intervention/"]["links"].append(
    ("Traitement des punaises de lit, ville par ville", [("Punaises de lit %s" % n, "/punaises-de-lit-%s/" % s) for s, n, *_ in _PV]))
